DROP TABLE IF EXISTS `concept_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concept_answer` (
  `concept_answer_id` int NOT NULL AUTO_INCREMENT,
  `concept_id` int NOT NULL DEFAULT '0',
  `answer_concept` int DEFAULT NULL,
  `answer_drug` int DEFAULT NULL,
  `creator` int NOT NULL DEFAULT '0',
  `date_created` datetime NOT NULL,
  `sort_weight` double DEFAULT NULL,
  `uuid` char(38) NOT NULL,
  PRIMARY KEY (`concept_answer_id`),
  UNIQUE KEY `concept_answer_uuid_index` (`uuid`) USING BTREE,
  KEY `answer` (`answer_concept`) USING BTREE,
  KEY `answers_for_concept` (`concept_id`) USING BTREE,
  KEY `answer_creator` (`creator`) USING BTREE,
  KEY `answer_answer_drug_fk` (`answer_drug`) USING BTREE,
  CONSTRAINT `concept_answer_ibfk_1` FOREIGN KEY (`answer_concept`) REFERENCES `concept` (`concept_id`),
  CONSTRAINT `concept_answer_ibfk_2` FOREIGN KEY (`concept_id`) REFERENCES `concept` (`concept_id`),
  CONSTRAINT `concept_answer_ibfk_3` FOREIGN KEY (`answer_drug`) REFERENCES `drug` (`drug_id`),
  CONSTRAINT `concept_answer_ibfk_4` FOREIGN KEY (`creator`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7376317 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

