--
-- Table structure for table `concept_proposal`
--

DROP TABLE IF EXISTS `concept_proposal`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concept_proposal` (
  `concept_proposal_id` int NOT NULL AUTO_INCREMENT,
  `concept_id` int DEFAULT NULL,
  `encounter_id` int DEFAULT NULL,
  `original_text` varchar(255) NOT NULL DEFAULT '',
  `final_text` varchar(255) DEFAULT NULL,
  `obs_id` int DEFAULT NULL,
  `obs_concept_id` int DEFAULT NULL,
  `state` varchar(32) NOT NULL DEFAULT 'UNMAPPED',
  `comments` varchar(255) DEFAULT NULL,
  `creator` int NOT NULL DEFAULT '0',
  `date_created` datetime NOT NULL,
  `changed_by` int DEFAULT NULL,
  `date_changed` datetime DEFAULT NULL,
  `locale` varchar(50) NOT NULL DEFAULT '',
  `uuid` char(38) NOT NULL,
  PRIMARY KEY (`concept_proposal_id`),
  UNIQUE KEY `concept_proposal_uuid_index` (`uuid`) USING BTREE,
  KEY `user_who_changed_proposal` (`changed_by`) USING BTREE,
  KEY `concept_for_proposal` (`concept_id`) USING BTREE,
  KEY `user_who_created_proposal` (`creator`) USING BTREE,
  KEY `encounter_for_proposal` (`encounter_id`) USING BTREE,
  KEY `proposal_obs_concept_id` (`obs_concept_id`) USING BTREE,
  KEY `proposal_obs_id` (`obs_id`) USING BTREE,
  CONSTRAINT `concept_proposal_ibfk_1` FOREIGN KEY (`concept_id`) REFERENCES `concept` (`concept_id`),
  CONSTRAINT `concept_proposal_ibfk_2` FOREIGN KEY (`encounter_id`) REFERENCES `encounter` (`encounter_id`),
  CONSTRAINT `concept_proposal_ibfk_3` FOREIGN KEY (`obs_concept_id`) REFERENCES `concept` (`concept_id`),
  CONSTRAINT `concept_proposal_ibfk_4` FOREIGN KEY (`obs_id`) REFERENCES `obs` (`obs_id`),
  CONSTRAINT `concept_proposal_ibfk_5` FOREIGN KEY (`changed_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `concept_proposal_ibfk_6` FOREIGN KEY (`creator`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

